'use strict';

// MAJOR.MINOR.PATCH with optional -prerelease, per semver.org 2.0.0
const SEMVER = /^v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-([0-9A-Za-z.-]+))?$/;

function parse(version) {
  const m = SEMVER.exec(version);
  if (!m) throw new Error(`Invalid semver: ${version}`);
  return {
    major: Number(m[1]),
    minor: Number(m[2]),
    patch: Number(m[3]),
    prerelease: m[4] || null,
  };
}

// major = breaking change, minor = new feature, patch = bug fix
function bump(version, type) {
  const v = parse(version);
  switch (type) {
    case 'major':
      return `${v.major + 1}.0.0`; // reset minor and patch
    case 'minor':
      return `${v.major}.${v.minor + 1}.0`; // reset patch
    case 'patch':
      // 1.2.3-rc.1 -> 1.2.3 : a prerelease ships as its own version
      return v.prerelease
        ? `${v.major}.${v.minor}.${v.patch}`
        : `${v.major}.${v.minor}.${v.patch + 1}`;
    default:
      throw new Error(`Unknown bump type: ${type}`);
  }
}

// Map a Conventional Commit subject to a bump type
function bumpFromCommit(subject) {
  if (/^\w+(\(.+\))?!:/.test(subject) || subject.includes('BREAKING CHANGE')) return 'major';
  if (/^feat(\(.+\))?:/.test(subject)) return 'minor';
  return 'patch';
}

module.exports = { parse, bump, bumpFromCommit };

'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { parse, bump, bumpFromCommit } = require('../src/semver');

test('parse accepts a v-prefixed tag', () => {
  assert.deepEqual(parse('v1.4.2'), { major: 1, minor: 4, patch: 2, prerelease: null });
});

test('parse rejects leading zeros', () => {
  assert.throws(() => parse('01.2.3'));
});

test('bump resets lower fields', () => {
  assert.equal(bump('1.4.2', 'major'), '2.0.0');
  assert.equal(bump('1.4.2', 'minor'), '1.5.0');
  assert.equal(bump('1.4.2', 'patch'), '1.4.3');
});

test('patch on a prerelease drops the suffix', () => {
  assert.equal(bump('2.0.0-rc.1', 'patch'), '2.0.0');
});

test('conventional commits map to bump types', () => {
  assert.equal(bumpFromCommit('feat: add parse()'), 'minor');
  assert.equal(bumpFromCommit('fix(api): null check'), 'patch');
  assert.equal(bumpFromCommit('feat!: drop Node 18'), 'major');
});

