{
  "name": "gha-ci-node-demo",
  "version": "1.0.0",
  "description": "Sample app for GitHub Actions CI: lint, matrix test, build",
  "type": "module",
  "main": "src/price.js",
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "lint": "eslint .",
    "test": "node --test",
    "build": "rm -rf dist && mkdir dist && cp -r src package.json dist/"
  },
  "devDependencies": {
    "@eslint/js": "^9.0.0",
    "eslint": "^9.0.0",
    "globals": "^16.0.0"
  }
}

// ESLint v9 flat config. `npm run lint` fails the CI lint job on any error.
import js from "@eslint/js";
import globals from "globals";

export default [
  // Never lint build output or dependencies
  { ignores: ["dist/", "node_modules/"] },

  // ESLint's recommended rule set
  js.configs.recommended,

  {
    languageOptions: {
      ecmaVersion: "latest",
      sourceType: "module", // matches "type": "module" in package.json
      globals: globals.node
    },
    rules: {
      "no-unused-vars": "error", // an unused variable breaks the PR check
      eqeqeq: "error"
    }
  }
];

// Small pure functions so tests run fast and deterministically in CI.

const GST_RATE = 0.18; // standard GST slab used for this demo

/**
 * Apply a percentage discount to a price in rupees.
 * Throws on invalid input so tests can check error handling.
 */
export function applyDiscount(priceInr, percent) {
  if (typeof priceInr !== "number" || priceInr < 0) {
    throw new RangeError("price must be a non-negative number");
  }
  if (percent < 0 || percent > 100) {
    throw new RangeError("percent must be between 0 and 100");
  }
  return round2(priceInr * (1 - percent / 100));
}

/** Add GST to a net price. */
export function withGst(priceInr) {
  return round2(priceInr * (1 + GST_RATE));
}

/** Round to 2 decimal places (paise). */
function round2(value) {
  return Math.round(value * 100) / 100;
}

// Uses Node's built-in test runner (node:test), so no extra test framework.
// `node --test` finds files named *.test.js automatically.
import { test } from "node:test";
import assert from "node:assert/strict";
import { applyDiscount, withGst } from "../src/price.js";

test("applies a 10% discount", () => {
  assert.equal(applyDiscount(1000, 10), 900);
});

test("0% discount keeps the price", () => {
  assert.equal(applyDiscount(499.99, 0), 499.99);
});

test("rejects a discount above 100%", () => {
  assert.throws(() => applyDiscount(100, 150), RangeError);
});

test("rejects a negative price", () => {
  assert.throws(() => applyDiscount(-1, 10), RangeError);
});

test("adds 18% GST", () => {
  // Checkpoint: change 1180 to 1200, open a PR, and watch the merge get blocked.
  assert.equal(withGst(1000), 1180);
});

