// orders-api: minimal REST API backed by PostgreSQL.
package main

import (
	"context"
	"encoding/json"
	"log"
	"net/http"
	"os"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

type Order struct {
	ID   int    `json:"id"`
	Item string `json:"item"`
	Qty  int    `json:"qty"`
}

func main() {
	ctx := context.Background()
	// DATABASE_URL is set in compose.yaml; the host "db" is the Compose service name.
	pool, err := pgxpool.New(ctx, os.Getenv("DATABASE_URL"))
	if err != nil {
		log.Fatal(err)
	}
	// Retry briefly in case the database is still warming up.
	for i := 0; i < 10 && pool.Ping(ctx) != nil; i++ {
		time.Sleep(2 * time.Second)
	}
	if _, err := pool.Exec(ctx, `CREATE TABLE IF NOT EXISTS orders (id SERIAL PRIMARY KEY, item TEXT NOT NULL, qty INT NOT NULL)`); err != nil {
		log.Fatal(err)
	}

	mux := http.NewServeMux() // Go 1.22+ method-aware routing
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) { w.Write([]byte("ok")) })
	mux.HandleFunc("GET /orders", func(w http.ResponseWriter, r *http.Request) {
		rows, err := pool.Query(r.Context(), `SELECT id, item, qty FROM orders ORDER BY id`)
		if err != nil {
			http.Error(w, err.Error(), 500)
			return
		}
		defer rows.Close()
		orders := []Order{}
		for rows.Next() {
			var o Order
			rows.Scan(&o.ID, &o.Item, &o.Qty)
			orders = append(orders, o)
		}
		json.NewEncoder(w).Encode(orders)
	})
	mux.HandleFunc("POST /orders", func(w http.ResponseWriter, r *http.Request) {
		var o Order
		if err := json.NewDecoder(r.Body).Decode(&o); err != nil || o.Item == "" {
			http.Error(w, "invalid order", 400)
			return
		}
		err := pool.QueryRow(r.Context(), `INSERT INTO orders (item, qty) VALUES ($1, $2) RETURNING id`, o.Item, o.Qty).Scan(&o.ID)
		if err != nil {
			http.Error(w, err.Error(), 500)
			return
		}
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(o)
	})

	port := os.Getenv("PORT") // 8080, matches EXPOSE and the Compose port mapping
	log.Printf("listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, mux))
}

