"""Tiny HTTP app for the CKAD step. Stdlib only, listens on PORT (default 8080)."""
import json
import os
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

PORT = int(os.environ.get("PORT", "8080"))
MESSAGE = os.environ.get("APP_MESSAGE", "hello")            # injected from ConfigMap hello-config
TOKEN_SET = bool(os.environ.get("API_TOKEN"))                # injected from Secret hello-secret; never print it
WARMUP_SECONDS = int(os.environ.get("WARMUP_SECONDS", "5"))  # readiness fails until warm-up ends
STARTED = time.time()


class Handler(BaseHTTPRequestHandler):
    def _send(self, code, body):
        data = json.dumps(body).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def do_GET(self):
        if self.path == "/healthz":
            # startupProbe + livenessProbe: is the process alive?
            self._send(200, {"status": "ok"})
        elif self.path == "/ready":
            # readinessProbe: should the Service send traffic here yet?
            if time.time() - STARTED >= WARMUP_SECONDS:
                self._send(200, {"ready": True})
            else:
                self._send(503, {"ready": False})
        elif self.path == "/":
            self._send(200, {
                "message": MESSAGE,
                "pod": os.environ.get("POD_NAME", "unknown"),  # Downward API, shows load balancing
                "tokenConfigured": TOKEN_SET,
            })
        else:
            self._send(404, {"error": "not found"})

    def log_message(self, fmt, *args):
        # Log to stdout so `kubectl logs` shows every request
        print(f"{self.address_string()} {fmt % args}", flush=True)


if __name__ == "__main__":
    print(f"listening on :{PORT}", flush=True)
    ThreadingHTTPServer(("0.0.0.0", PORT), Handler).serve_forever()

