terraform {
  # use_lockfile (S3 native locking) needs Terraform 1.10+
  required_version = ">= 1.10"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0" # allow 6.x minor/patch updates, block 7.0
    }
  }

  # Remote backend: state lives in S3, not on a laptop.
  # Backend blocks cannot use variables or locals.
  backend "s3" {
    bucket       = "mc-tfstate-CHANGE-ME"
    key          = "iac-demo/terraform.tfstate" # workspaces are stored under env:/<name>/
    region       = "ap-south-1"
    encrypt      = true # server-side encryption of the state object
    use_lockfile = true # writes a .tflock object in S3; no DynamoDB table needed
  }
}

provider "aws" {
  region = var.region

  # Tags applied to every taggable resource from this provider
  default_tags {
    tags = {
      Project     = "mc-iac-demo"
      Environment = local.env
      ManagedBy   = "terraform"
    }
  }
}

variable "region" {
