  type = map(object({ cidr = string, db_class = string, desired_count = number }))
  default = {
    dev  = { cidr = "10.10.0.0/16", db_class = "db.t4g.micro", desired_count = 1 }
    prod = { cidr = "10.20.0.0/16", db_class = "db.t4g.small", desired_count = 2 }
  }
}

# Data source: READS existing info, creates nothing
data "aws_availability_zones" "available" {
