  name     = "mc-demo-${local.env}"
  settings = var.env_settings[local.env] # fails clearly if workspace is unknown
  azs      = slice(data.aws_availability_zones.available.names, 0, 2)
}

module "network" {
  source = "./modules/network"
  name   = local.name
  cidr   = local.settings.cidr
  azs    = local.azs
}

module "app" {
