}

module "db" {
  source         = "./modules/db"
  name           = local.name
  vpc_id         = module.network.vpc_id
  subnet_ids     = module.network.private_subnet_ids
  app_sg_id      = module.app.security_group_id # only the app may reach the DB
  instance_class = local.settings.db_class
}

# Refactor safely: if this module was once called "vpc", move state instead of recreating
moved {
  from = module.vpc
  to   = module.network
}

# Import example (uncomment with a real ID, then plan):
