# Orders API instrumented with RED metrics using prometheus_client.
import os, random, time
from flask import Flask, g, jsonify, request
from prometheus_client import Counter, Histogram, make_wsgi_app
from werkzeug.middleware.dispatcher import DispatcherMiddleware

ERROR_RATE = float(os.getenv("ERROR_RATE", "0.01"))  # share of requests that fail with 500
SLOW_RATE = float(os.getenv("SLOW_RATE", "0.02"))    # share of requests that take ~1s
PORT = int(os.getenv("PORT", "8080"))

app = Flask(__name__)

# Rate + Errors: one counter, errors are the code=~"5.." subset.
REQUESTS = Counter("http_requests_total", "HTTP requests", ["route", "method", "code"])
# Duration: histogram so Prometheus can compute any quantile with histogram_quantile().
LATENCY = Histogram(
    "http_request_duration_seconds", "HTTP request duration", ["route", "method"],
    buckets=(0.05, 0.1, 0.25, 0.5, 1.0, 2.5),
)

@app.before_request
def start_timer():
    g.start = time.perf_counter()

@app.after_request
def record_metrics(resp):
    # Use the route template, not the raw path, to keep label cardinality low.
    route = request.url_rule.rule if request.url_rule else "unmatched"
    LATENCY.labels(route, request.method).observe(time.perf_counter() - g.start)
    REQUESTS.labels(route, request.method, str(resp.status_code)).inc()
    return resp

@app.get("/api/orders")
def list_orders():
    time.sleep(1.0 if random.random() < SLOW_RATE else random.uniform(0.01, 0.08))
    if random.random() < ERROR_RATE:
        return jsonify(error="database timeout"), 500  # simulated dependency failure
    return jsonify(orders=[{"id": 1, "item": "chai"}, {"id": 2, "item": "samosa"}])

@app.get("/healthz")
def healthz():
    return "ok"

# Serve Prometheus text format on /metrics (pull model: Prometheus scrapes us).
app.wsgi_app = DispatcherMiddleware(app.wsgi_app, {"/metrics": make_wsgi_app()})

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=PORT, threaded=True)

// k6 load test: steady 20 requests/second so the SLI has enough traffic.
import http from 'k6/http';
import { check } from 'k6';

const BASE_URL = __ENV.BASE_URL || 'http://localhost:8080';

export const options = {
  scenarios: {
    steady: {
      executor: 'constant-arrival-rate', // fixed request rate, independent of latency
      rate: 20,
      timeUnit: '1s',
      duration: '6m',                    // long enough for 5m window + for: 2m
      preAllocatedVUs: 20,
      maxVUs: 50,
    },
  },
  thresholds: {
    http_req_failed: ['rate<0.005'],     // mirrors the 99.5% SLO; fails when we inject errors
    http_req_duration: ['p(99)<1000'],
  },
};

export default function () {
  const res = http.get(`${BASE_URL}/api/orders`);
  check(res, { 'status is 200': (r) => r.status === 200 });
}
